#include "ControlEdits.h"
static void testMasterProcessing(const File& root,Assets& assets){
    auto p=emptyProject();p.tracks.resize(1);p.patterns.resize(1);p.patterns[0].lanes.resize(1);p.patterns[0].lanes[0].clear();p.bpm=120;p.loop=false;p.master=1;p.songMode=true;p.clips.clear();
    auto& track=p.tracks[0];track=Track{};track.name="Dry sampler";track.instrument=Instrument::sample;track.volume=1;
    expect(!p.masterSoftClip&&track.send==0&&!track.mixer.reverb&&!track.mixer.chorus.enabled&&!track.mixer.flanger.enabled&&!track.mixer.phaser.enabled,"new sampler and master have no enabled saturation or time effects");
    AudioBuffer<float> source(2,24000);source.clear();for(int i=0;i<12000;++i){source.setSample(0,i,(float)(.7*std::sin(i*.13)+.15*std::cos(i*.21)));source.setSample(1,i,(float)(.3*std::cos(i*.07)));}
    auto file=root.getChildFile("master-dry-source.wav");auto stream=file.createOutputStream();WavAudioFormat format;std::unique_ptr<AudioFormatWriter> writer(stream?format.createWriterFor(stream.get(),48000,2,32,{},0):nullptr);
    bool written=writer&&writer->writeFromAudioSampleBuffer(source,0,source.getNumSamples());if(writer)stream.release();writer.reset();String error;auto* sample=written?assets.load(file,error):nullptr;expect(sample!=nullptr,"dry signal fixture is a decoded stereo WAV");if(!sample)return;
    track.samplePath=file.getFullPathName();p.songMode=false;p.patterns[0].lanes[0]={{0,2,60,1}};
    auto dry=render(p,assets,root,48000,127);float gain=0,filter[2]={};double largest=0;float coefficient=(float)(1-std::exp(-2*MathConstants<double>::pi*16000/48000));
    for(int i=0;i<48000;++i){gain+=(1-gain)*.002f;double envelope=jmin(1.,i/(48000.*.005));for(int c=0;c<2;++c){float input=i<24000?(float)(sample->audio.getSample(c,i)*envelope):0;filter[c]+=(input-filter[c])*coefficient;float pan=(float)(c==0?std::cos(MathConstants<double>::pi/4):std::sin(MathConstants<double>::pi/4));float expected=filter[c]*gain*pan;largest=jmax(largest,std::abs((double)dry.getSample(c,i)-expected));}}
    expect(largest<.000001,"default sampler output matches independent envelope/filter/fader/pan calculation with no hidden master coloration");
    expect(dry.getMagnitude(0,20000,28000)<.000001f,"zero-send sampler produces no delayed or reverberant tail");
    auto clipped=p;clipped.masterSoftClip=true;auto soft=render(clipped,assets,root,48000,733);bool exact=true;for(int c=0;c<2;++c)for(int i=0;i<48000;++i)exact&=soft.getSample(c,i)==std::tanh(dry.getSample(c,i));expect(exact,"visible saturation switch reproduces the former unconditional tanh master exactly");
    auto json=projectToJson(p);Project read;expect(projectFromJson(json,read).wasOk()&&!read.masterSoftClip&&read.delayReturn==.5f,"schema nineteen roundtrips dry master defaults");
    json.getDynamicObject()->setProperty("schema",18);json.getDynamicObject()->removeProperty("masterSoftClip");json.getDynamicObject()->removeProperty("delayReturn");expect(projectFromJson(json,read).wasOk()&&read.masterSoftClip&&read.delayReturn==.5f,"legacy projects migrate to the original saturation and fixed delay return");
    auto legacy=render(read,assets,root,48000,211);bool same=true;for(int c=0;c<2;++c)for(int i=0;i<48000;++i)same&=legacy.getSample(c,i)==soft.getSample(c,i);expect(same,"legacy migration preserves actual audio sample for sample across callback sizes");
    for(const char* property:{"masterSoftClip","delayReturn"}){auto bad=projectToJson(p);bad.getDynamicObject()->removeProperty(property);auto before=JSON::toString(projectToJson(read));expect(projectFromJson(bad,read).failed()&&JSON::toString(projectToJson(read))==before,"missing master processing settings reject atomically");}
    for(var bad:{var(-.1),var(1.01),var("0.5"),var(std::numeric_limits<double>::quiet_NaN())}){auto invalid=projectToJson(p);invalid.getDynamicObject()->setProperty("delayReturn",bad);expect(projectFromJson(invalid,read).failed(),"invalid master return cannot enter a project");}
    auto send=p;send.tracks[0].send=.8f;send.delayFeedback=0;send.delayReturn=.5f;auto wet=render(send,assets,root,48000);send.delayReturn=0;auto muted=render(send,assets,root,48000);bool nulled=true;for(int c=0;c<2;++c)for(int i=0;i<48000;++i)nulled&=muted.getSample(c,i)==dry.getSample(c,i);expect(nulled&&wet.getMagnitude(0,20000,10000)>.01f,"return zero is genuinely dry while feedback zero still permits the first echo");
    auto engine=makeEngine(p,assets,root);AudioBuffer<float> out(2,512);engine->playing=false;engine->preview(sample);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(engine->previewPlaying.load(),"browser preview can play while stopped");engine->start();engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->previewPlaying.load(),"starting transport cancels an already audible preview");
    engine->stop();engine->preview(sample);engine->start();engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->previewPlaying.load(),"queued preview before Play cannot double the song");engine->preview(sample);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(engine->previewPlaying.load(),"explicit new preview during song playback remains available");engine->audition(0,60,true);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->previewPlaying.load(),"playing a sampler note cancels preview doubling");
    bool queued=true;for(int i=0;i<32;++i)queued&=engine->preview(sample);expect(queued&&!engine->preview(sample)&&engine->preview(nullptr),"Stop preview always succeeds even with a full command queue");engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->previewPlaying.load(),"full stale preview queue is discarded after cancellation");
    engine->preview(sample);engine->cancelPreview();engine->preview(sample,.1,.2);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(engine->previewPlaying.load()&&engine->previewPosition.load()>.1,"preview requested after cancellation is retained in order");
    Engine::TakePlan take;take.startBeat=take.gateBeat=0;take.endBeat=2;expect(engine->beginTake(take),"recording fixture starts");engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->previewPlaying.load(),"recording cancels independent sample preview");
    Project edited;expect(applyControlEdits(p,JSON::parse(R"([{"op":"set_song","masterSoftClip":true,"delayReturn":0.2,"delayFeedback":0.6}])"),edited).wasOk()&&edited.masterSoftClip&&edited.delayReturn==.2f&&edited.delayFeedback==.6f,"MCP edits all master processing settings in a validated atomic batch");
    for(auto invalid:{R"([{"op":"set_song","masterSoftClip":1}])",R"([{"op":"set_song","delayReturn":true}])",R"([{"op":"set_song","delayReturn":1.01}])",R"([{"op":"set_song","delayReturn":-0.01}])",R"([{"op":"set_song","masterSoftClip":false},{"op":"set_song","delayReturn":"0"}])"}){auto candidate=edited;auto before=JSON::toString(projectToJson(candidate));expect(applyControlEdits(p,JSON::parse(invalid),candidate).failed()&&JSON::toString(projectToJson(candidate))==before,"invalid MCP master edits leave the entire destination unchanged");}
}
